CREATE TABLE attribution_enrollments (
  participant_id TEXT PRIMARY KEY REFERENCES participants(id) ON DELETE CASCADE,
  namespace TEXT NOT NULL UNIQUE CHECK (length(namespace) = 64 AND namespace NOT GLOB '*[^0-9a-f]*'),
  created_at TEXT NOT NULL
) STRICT

CREATE TRIGGER storage_ingestion_change_validate BEFORE INSERT ON storage_ingestion_changes
BEGIN
  SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM storage_source_state WHERE singleton=1)
    THEN RAISE(ABORT,'storage_source_uninitialized') END;
  SELECT CASE WHEN NEW.revision != COALESCE((SELECT revision FROM storage_owner_revisions WHERE owner_digest=NEW.owner_digest),0)+1
    THEN RAISE(ABORT,'storage_owner_revision_conflict') END;
  SELECT CASE WHEN EXISTS(SELECT 1 FROM storage_owner_revisions WHERE owner_digest=NEW.owner_digest AND state='erased')
    THEN RAISE(ABORT,'storage_owner_erased') END;
  SELECT CASE WHEN NEW.kind='source-updated' AND NOT EXISTS(
      SELECT 1 FROM storage_owner_revisions WHERE owner_digest=NEW.owner_digest AND state='active')
    THEN RAISE(ABORT,'storage_owner_ineligible') END;
  SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM storage_owner_revisions WHERE owner_digest=NEW.owner_digest)
      AND NEW.kind!='owner-active'
    THEN RAISE(ABORT,'storage_owner_uninitialized') END;
  SELECT CASE WHEN NEW.authority_epoch != COALESCE((SELECT authority_epoch FROM storage_owner_revisions WHERE owner_digest=NEW.owner_digest),0)
      + CASE WHEN NEW.kind='source-updated' THEN 0 ELSE 1 END
    THEN RAISE(ABORT,'storage_authority_conflict') END;
  SELECT CASE WHEN NEW.public_authority_epoch != (SELECT authority_epoch FROM storage_source_state WHERE singleton=1)
      + CASE WHEN NEW.kind='source-updated' THEN 0 ELSE 1 END
    THEN RAISE(ABORT,'storage_public_authority_conflict') END;
END

CREATE TRIGGER telemetry_transport_floor_created AFTER INSERT ON participants
BEGIN
  INSERT INTO telemetry_transport_participant_floors (
    participant_id, minimum_rank, changed_at
  ) VALUES (
    NEW.id,
    CASE WHEN NEW.owner_kind = 'accountless' THEN 11 ELSE 1 END,
    strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
  );
END

CREATE TRIGGER telemetry_usage_correction_participant_erasure
BEFORE DELETE ON participants
BEGIN
  UPDATE storage_v11_owner_links SET state='erased'
   WHERE participant_id=OLD.id AND state!='erased';




  DELETE FROM telemetry_usage_correction_facts
   WHERE history_id IN (
     SELECT id FROM telemetry_usage_correction_history WHERE participant_id=OLD.id
   );
  DELETE FROM telemetry_usage_correction_history WHERE participant_id=OLD.id;
END

CREATE TRIGGER telemetry_v11_head_insert_publish AFTER INSERT ON telemetry_v11_domain_heads
BEGIN
  UPDATE telemetry_v11_domain_predecessors SET consumed_at = NEW.updated_at
    WHERE token_hash = (SELECT predecessor_token_hash FROM telemetry_v11_domains WHERE id = NEW.generation_id);
  UPDATE community_analytical_input_versions SET revision = revision + 1 WHERE participant_id = NEW.participant_id;
  UPDATE community_snapshot_mutation_control
     SET mutation_epoch = mutation_epoch + 1
   WHERE singleton_id = 1 AND EXISTS (
     SELECT 1 FROM community_public_source_owners p
      WHERE p.participant_id = NEW.participant_id
   );
END

CREATE TRIGGER typed_v11_allocation_advance AFTER INSERT ON typed_v11_chunk_allocations
BEGIN
  UPDATE typed_v11_admission_state SET next_source_row_id = NEW.first_source_row_id + NEW.record_count
    WHERE id = 1 AND namespace_id = NEW.namespace_id AND next_source_row_id = NEW.first_source_row_id;
  SELECT CASE WHEN changes() != 1 THEN RAISE(ABORT,'typed_v11_allocator_race') END;
END

